command:
python3 - <<'EOF'
from pathlib import Path
p = Path("src/web/src/text/rowNames.js")
t = p.read_text()
a = '''// a row by its word and number, with a place in it after a colon: a line, a span of lines, or "section N"
const NAMED = new RegExp(`\\\\b(${WORD_PATTERN}) #?(\\\\d+)(?::(\\\\d+(?:-\\\\d+)?|section \\\\d+))?\\\\b`, "gi");

const chips = (text) =>
    text.replace(
        NAMED,
        (whole, word, id, at = "") =>
            `<a class="row-pill" href="#" data-peek="${tableOfWord(word)}:${id}"${at ? ` data-sub="${at}"` : ""}>${word} <span class="row-pill-num">${id}${at ? `:${at}` : ""}</span></a>`
    );'''
assert a in t, "missing"
b = '''// a row by its word and number, with a place in it after a colon: a line, a span of lines, or "section N"; or its number in parentheses, as in "the joining task (1463)"
const NAMED = new RegExp(`\\\\b(${WORD_PATTERN}) (?:#?(\\\\d+)(?::(\\\\d+(?:-\\\\d+)?|section \\\\d+))?\\\\b|\\\\((\\\\d+)\\\\))`, "gi");

const chips = (text) =>
    text.replace(
        NAMED,
        (whole, word, bare, at = "", enclosed) => {
            const id = bare || enclosed;
            return `<a class="row-pill" href="#" data-peek="${tableOfWord(word)}:${id}"${at ? ` data-sub="${at}"` : ""}>${word} <span class="row-pill-num">${id}${at ? `:${at}` : ""}</span></a>`;
        }
    );'''
p.write_text(t.replace(a, b))
p = Path("src/web/tests/rowNames.test.js")
t = p.read_text()
t += '''
test("a row number in parentheses after its word is a chip too", () => {
    const into = document.createElement("div");
    into.innerHTML = render("the joining task (1463) and plan (24)", {env: ""});
    expect([...into.querySelectorAll("a[data-peek]")].map((c) => c.dataset.peek)).toEqual(["tasks:1463", "plans:24"]);
    expect(into.textContent).toBe("the joining task 1463 and plan 24");
});
'''
p.write_text(t)
EOF
(cd src/web && npx vitest run tests/rowNames.test.js 2>&1 | tail -6)

